begin;
-- restore original policies/functions captured from staging catalog (2026-11-07)
drop policy if exists enq_leads_read on public.enquiries;
create policy enq_leads_read on public.enquiries for select using (kind='requirement' and seller_can_see_leads() and lead_matches_my_company(category_id));
drop policy if exists enq_staff_read on public.enquiries; create policy enq_staff_read on public.enquiries for select using (is_staff());
drop policy if exists enq_staff_upd on public.enquiries; create policy enq_staff_upd on public.enquiries for update using (is_staff()) with check (is_staff());
drop policy if exists epriv_read on public.enquiry_private; create policy epriv_read on public.enquiry_private for select using (enquiry_buyer(enquiry_id)=auth.uid() or is_staff());
create or replace function public.seller_can_see_leads() returns boolean language sql stable security definer set search_path to 'public','pg_temp' as $$ select exists(select 1 from company_members m join companies c on c.id=m.company_id where m.user_id=auth.uid() and m.status='active' and c.claim_status='approved' and c.directory_status='published' and m.role in ('owner','manager','sales')) $$;
create or replace function public.lead_matches_my_company(cat integer) returns boolean language sql stable security definer set search_path to 'public','pg_temp' as $$ select exists(select 1 from company_members m join companies c on c.id=m.company_id where m.user_id=auth.uid() and m.status='active' and c.claim_status='approved' and c.directory_status='published' and m.role in ('owner','manager','sales') and (cat is null or exists(select 1 from company_categories cc where cc.company_id=c.id and cc.category_id=cat))) $$;
create or replace function public.staff_mark_enquiry(p_enquiry uuid, p_delivery enquiry_delivery, p_note text, p_provider_ref text default null) returns void language plpgsql security definer set search_path to 'public','pg_temp' as $$ begin if not is_staff() then raise exception 'staff only' using errcode='42501'; end if; if p_delivery='sent_external' and coalesce(trim(p_provider_ref),'')='' then raise exception 'sent_external requires a provider reference'; end if; update enquiries set delivery=p_delivery, delivery_note=left(coalesce(p_note,'')||case when p_provider_ref is not null then ' [ref '||p_provider_ref||']' else '' end,500) where id=p_enquiry; if not found then raise exception 'enquiry not found'; end if; end $$;
drop function if exists public.create_requirement(uuid,text,text,text,text,text,text,text,text,text), public.buyer_requirement_status(uuid), public.admin_rematch(uuid), public.admin_rematch_for_company(uuid), public.admin_assign_lead(uuid,uuid), public.staff_update_lead(uuid,public.lead_status,text,timestamptz), public.staff_my_leads(), public.staff_log_call(uuid,uuid,text,text), public.admin_lead_overview(), public.admin_set_routing_settings(integer,integer,boolean,boolean), public._match_requirement(uuid);
drop table public.lead_distribution_events, public.lead_status_history, public.lead_cases, public.requirement_matches, public.requirement_details, public.lead_routing_settings;
drop function if exists public._lead_case_history(), public.seller_lead_visible(uuid), public.seller_match_visible(uuid,uuid), public._company_lead_eligible(uuid,integer), public.staff_can_access_company(uuid,uuid,uuid), public.staff_can_see_case(uuid), public.staff_can_see_enquiry(uuid);
drop type public.match_route, public.lead_status;
commit;
